const inputData = $input.first().json;
const searchQuery = inputData.searchQuery || "mutuelle santé";
const country = inputData.Country || "FR"; 
const baseUrl = 'https://www.facebook.com/ads/library/';
const params = `?active_status=active&ad_type=all&country=${country}&q=${encodeURIComponent(searchQuery )}&search_type=keyword_unordered`;

return [{
  json: {
    search_query: searchQuery,
    country: country,
    final_url: baseUrl + params
  }
}];

const processedAds = [];
const now = new Date();

for (const item of $input.all()) {
  const data = item.json;
  const snap = data.snapshot || {};

  // EXTRACTION TOTALE
  const isDCOPlaceholder = (str) => typeof str === 'string' && str.includes('{{') && str.includes('}}');
  const getDataFromCards = () => {
    if (snap.cards && snap.cards.length > 0) {
      const firstCard = snap.cards[0];
      return {
        headline: firstCard.title || firstCard.body || "Pas de titre",
        body_text: firstCard.body || "Pas de texte",
        link_description: firstCard.linkDescription || "",
        video_url: firstCard.videoHdUrl || firstCard.videoSdUrl || null,
        is_from_cards: true
      };
    }
    return null;
  };

  let headline = snap.title || snap.ad_title || "Pas de titre";
  let body_text = snap.body?.text || snap.ad_body || "Pas de texte";
  let link_description = snap.linkDescription || snap.link_description || "";
  let is_dco_ad = false;
  let is_data_from_cards = false;

  if (isDCOPlaceholder(headline) || isDCOPlaceholder(body_text) || isDCOPlaceholder(link_description)) {
    is_dco_ad = true;
    const cardData = getDataFromCards();
    if (cardData) {
      headline = cardData.headline;
      body_text = cardData.body_text;
      link_description = cardData.link_description;
      is_data_from_cards = true;
    }
  }

  const ad_copy = body_text;

  // VISUALS
  let visual_urls = [];
  if (snap.images && snap.images.length > 0) {
    visual_urls = snap.images.map(img => 
      img.originalImageUrl || img.resizedImageUrl || (img.imageCrops && img.imageCrops[0] ? img.imageCrops[0].originalImageUrl : null)
    ).filter(url => url);
  }

  if (visual_urls.length === 0 && snap.cards && snap.cards.length > 0) {
    for (const card of snap.cards) {
      if (card.originalImageUrl) visual_urls.push(card.originalImageUrl);
      else if (card.videoPreviewImageUrl) visual_urls.push(card.videoPreviewImageUrl);
    }
  }

  if (visual_urls.length === 0) {
    const fallbackUrl = data.imageUrl || (snap.cards && snap.cards[0] ? snap.cards[0].originalImageUrl : null) || data.ad_snapshot_url;
    if (fallbackUrl) visual_urls.push(fallbackUrl);
  }

  const visual_url = visual_urls.length > 0 ? visual_urls.join(", ") : null;
  const visual_urls_string = visual_urls.join(" | ");

  // AMÉLIORATION 1: Détection Variantes améliorée
  const has_variants = visual_urls.length > 1 || data.adHasMultipleVersions || snap.adHasMultipleVersions || false;
  const version_count = visual_urls.length > 1 ? visual_urls.length : (data.versionCount || snap.versionCount || (has_variants ? 2 : 1));

  // AUDIENCE EXTRACTION
  let dominant_age_range = "Unknown";
  let dominant_gender = "All";
  let age_gender_breakdown = "";
  let eu_total_reach = 0;
  let target_locations = "Inconnu";

  let aaa_info = null;
  if (data.ad_details && data.ad_details.aaa_info) {
    aaa_info = data.ad_details.aaa_info;
  } else if (snap.age_country_gender_reach_breakdown) {
    aaa_info = { age_country_gender_reach_breakdown: snap.age_country_gender_reach_breakdown };
  }

  if (data.ad_details && data.ad_details.aaa_info && data.ad_details.aaa_info.location_audience) {
    target_locations = data.ad_details.aaa_info.location_audience.map(l => l.name).join(', ');
  }

  if (aaa_info && aaa_info.age_country_gender_reach_breakdown && aaa_info.age_country_gender_reach_breakdown.length > 0) {
    eu_total_reach = aaa_info.eu_total_reach || 0;

    let countryData = aaa_info.age_country_gender_reach_breakdown.find(c => c.country === 'FR');
    if (!countryData && aaa_info.age_country_gender_reach_breakdown.length > 0) {
      countryData = aaa_info.age_country_gender_reach_breakdown[0];
    }

    if (countryData && countryData.age_gender_breakdowns && countryData.age_gender_breakdowns.length > 0) {
      let maxReach = 0;
      let maxGender = "All";

      for (const breakdown of countryData.age_gender_breakdowns) {
        const totalReach = (breakdown.male || 0) + (breakdown.female || 0) + (breakdown.unknown || 0);
        if (totalReach > maxReach) {
          maxReach = totalReach;
          dominant_age_range = breakdown.age_range;
          const femaleReach = breakdown.female || 0;
          const maleReach = breakdown.male || 0;
          if (femaleReach > maleReach) maxGender = "female";
          else if (maleReach > femaleReach) maxGender = "male";
          else maxGender = "All";
        }
      }
      dominant_gender = maxGender;
      age_gender_breakdown = countryData.age_gender_breakdowns
        .map(b => `${b.age_range}: M=${b.male||0} F=${b.female||0}`)
        .join(" | ");
    }
  }

  let videoUrl = data.videoUrl || (snap.videos && snap.videos[0] ? (snap.videos[0].video_hd_url || snap.videos[0].video_sd_url) : null);
  if (!videoUrl && snap.cards && snap.cards.length > 0) {
    for (const card of snap.cards) {
      if (card.videoHdUrl || card.videoSdUrl) {
        videoUrl = card.videoHdUrl || card.videoSdUrl;
        break;
      }
    }
  }

  const hasVideo = !!videoUrl;

  const startDate = new Date(data.adRunStartDate || data.startDateFormatted || snap.creation_time || now);
  const daysActive = Math.ceil(Math.abs(now - startDate) / (1000 * 60 * 60 * 24)) || 1;

  let score = 0;
  score += Math.min(daysActive * 1.5, 30);
  score += hasVideo ? 15 : 0;
  score += (version_count || 0) * 10;
  score += Math.min((eu_total_reach || 0) / 50000, 20);

  // AMÉLIORATION 4: Virality Score
  const virality_score = Math.min(
    Math.round(
      ((eu_total_reach || 0) / 100000) * 10 +      // Reach (max 10 pts)
      (version_count * 5) +                         // Variantes (5 pts par variante)
      (hasVideo ? 10 : 0) +                         // Vidéo (10 pts)
      (daysActive > 30 ? 10 : 0)                    // Durée (10 pts si > 30j)
    ), 
    100
  );

  // META NATIVE FORM EXTRACTION
  let native_questions_array = [];
  let form_type = 'external_landing_page';

  if (snap.extraTexts && snap.extraTexts.length > 0) {
    let currentQuestion = null;
    let currentChoices = [];
    let hasQuestions = false;

    for (const textObj of snap.extraTexts) {
      const txt = (textObj.text || "").trim();
      if (!txt) continue;

      const lower = txt.toLowerCase();

      if (lower.includes("conditions générales") || lower.includes("politique de confidentialité") || lower.includes("merci, vous avez terminé")) {
          if (currentQuestion) {
            native_questions_array.push({
              question: currentQuestion,
              type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
              choices: currentChoices.length > 0 ? currentChoices : null
            });
            currentQuestion = null;
            currentChoices = [];
          }
          continue;
      }

      if (txt.endsWith('?')) {
        hasQuestions = true;
        if (currentQuestion) {
          native_questions_array.push({
            question: currentQuestion,
            type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
            choices: currentChoices.length > 0 ? currentChoices : null
          });
        }
        currentQuestion = txt;
        currentChoices = [];
      } else if (currentQuestion && (["OUI", "NON"].includes(txt.toUpperCase()) || txt.includes('€') || lower.includes('je ne sais pas') || txt.match(/^[0-9]+.*[0-9]+$/))) {
        currentChoices.push(txt);
      } else if (["full name", "phone number", "email", "post code", "postal code"].includes(lower)) {
        if (currentQuestion) {
          native_questions_array.push({
            question: currentQuestion,
            type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
            choices: currentChoices.length > 0 ? currentChoices : null
          });
          currentQuestion = null;
          currentChoices = [];
        }
        native_questions_array.push({
            question: txt,
            type: 'standard_field',
            choices: null
        });
        hasQuestions = true;
      }
    }

    if (currentQuestion) {
      native_questions_array.push({
        question: currentQuestion,
        type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
        choices: currentChoices.length > 0 ? currentChoices : null
      });
    }

    if (hasQuestions) {
        form_type = 'native_meta_form';
    }
  }

  const parsed_form_text = native_questions_array.map(q => {
      if (q.type === 'multiple_choice') return `[Choix Multiple] ${q.question} -> Choix: ${q.choices.join(', ')}`;
      if (q.type === 'standard_field') return `[Donnée Demandée] ${q.question}`;
      return `[Question Ouverte] ${q.question}`;
  }).join('\n');

  // AMÉLIORATION 5: Créer colonnes question_1 à question_15
  const questionsObject = {};
  for (let i = 0; i < 15; i++) {
    const qIndex = i + 1;
    if (i < native_questions_array.length) {
      const q = native_questions_array[i];
      if (q.type === 'multiple_choice') {
        questionsObject[`question_${qIndex}`] = `[Choix Multiple] ${q.question} -> Choix: ${q.choices.join(', ')}`;
      } else if (q.type === 'standard_field') {
        questionsObject[`question_${qIndex}`] = `[Donnée Demandée] ${q.question}`;
      } else {
        questionsObject[`question_${qIndex}`] = `[Question Ouverte] ${q.question}`;
      }
    } else {
      questionsObject[`question_${qIndex}`] = "";
    }
  }

  processedAds.push({
    json: {
      ad_id: data.adArchiveID || data.id,
      brand: data.pageName || snap.page_name || "Inconnu",
      days_active: daysActive,
      performance_score: Math.round(score),

      headline: headline,
      body_text: body_text,
      link_description: link_description,
      ad_copy: ad_copy,

      visual_url: visual_url,
      visual_urls: visual_urls_string,
      image_count: visual_urls.length,
      has_image: visual_urls.length > 0,

      has_variants: has_variants,
      version_count: version_count,

      dominant_age_range: dominant_age_range,
      dominant_gender: dominant_gender,
      age_gender_breakdown: age_gender_breakdown,
      eu_total_reach: eu_total_reach,
      target_locations: target_locations,

      is_dco_ad: is_dco_ad,
      is_data_from_cards: is_data_from_cards,

      form_type: form_type,
      form_fields_json: form_type === 'native_meta_form' ? JSON.stringify(native_questions_array) : '',
      form_total_fields: native_questions_array.length,
      native_form_questions_plain: parsed_form_text,

      cta_type: data.ctaType || snap.cta_type || snap.cta_text || "LEARN_MORE",
      video_url: videoUrl,
      has_video: hasVideo,
      website_url: snap.linkUrl || data.adSnapshotUrl || snap.link_url || data.link || snap.website_url || "",
      landing_page_url: snap.linkUrl || data.adSnapshotUrl || snap.link_url || data.link || snap.website_url || "",

      // Amélioration 1: Variantes
      // Amélioration 4: Virality Score
      virality_score: virality_score,

      // Amélioration 5: Questions séparées
      ...questionsObject,

      // À remplir par les nœuds IA suivants:
      hook_type: "",
      why_it_works: "",
      takeaway_1: "",
      takeaway_2: "",
      takeaway_3: "",
      exit_hook: "",
      tunnel_friction_reasons_detailed: ""
    }
  });
}

return processedAds.sort((a, b) => b.json.performance_score - a.json.performance_score);

parameters.text:
Tu es un consultant expert en marketing d'assurance santé. Analyse cette publicité Facebook/Meta et retourne UNIQUEMENT un JSON valide.

**AD DATA**
Brand: {{ $json.brand }}
Days Active: {{ $json.days_active }}
Title: {{ $json.headline }}
Body: {{ $json.body_text }}
Link Description: {{ $json.link_description }}
Variants: {{ $json.version_count }}
Formulaire Natif Hook Brut: {{ $json.native_form_hook || 'N/A' }}
Questions du Formulaire: {{ $json.native_form_questions_plain || 'N/A' }}

**VISUAL ANALYSIS**
Vidéo: {{ $json.video_analysis || "Pas de données video" }}
Image: {{ $json.image_analysis || "Pas de données image" }}

**INSTRUCTIONS D'ANALYSE**
1. **Hook Type**: Quel est l'angle principal ? (Urgence, Économie, Autorité, Loi Lemoine, Sénior...)
2. **Why it works**: Pourquoi cette pub fonctionne-t-elle psychologiquement auprès des mutuelles santé ?
3. **Takeaways**: Extrais 3 secrets/insights clés pour répliquer le succès (takeaway_1, takeaway_2, takeaway_3).
4. **Hook de Sortie**: Formule l'appel à l'action / la promesse finale (ex: "Vérifiez vos droits en 30s", ou bien base-toi sur "Formulaire Natif Hook Brut").
5. **Tunnel Friction Reasons**: Analyse détaillée de la friction du formulaire. Y a-t-il trop de questions ? Les données demandées sont-elles sensibles (ex: téléphone = haute friction) ?
6. **Recommendations**: Comment améliorer ou durcir le tunnel pour obtenir des prospects plus chauds et moins de déchets ?

**RETURN THIS EXACT JSON STRUCTURE (ONLY JSON, NO MARKDOWN, NO ```):**
{
  "hook_type": "string (ex: Économie immédiate)",
  "why_it_works": "string (ex: Touche à la peur de payer trop cher)",
  "takeaway_1": "string (ex: Utiliser des couleurs bleues rassurantes)",
  "takeaway_2": "string (ex: Promesse chiffrée de 300€)",
  "takeaway_3": "string (ex: Ciblage explicite +55 ans)",
  "hook_de_sortie": "string (ex: Calculez votre devis sans engagement)",
  "tunnel_friction_reasons": "string (ex: Friction moyenne : 6 questions mais demande le numéro de téléphone)",
  "tunnel_recommendations": "string (ex: Remplacer le champ téléphone obligatoire par un SMS OTP pour filtrer les faux numéros)"
}

CRITICAL INSTRUCTION: You MUST output ONLY the raw JSON object. Do NOT add markdown blocks (```json). Do NOT add conversational text like 'Here is the JSON'. The very first character of your response MUST be `{` and the very last MUST be `}`.

