const formType = $json.form_type || 'external_landing_page';
const landingPageUrl = $json.landing_page_url || $json.website_url || $json.linkUrl || '';

if (formType === 'native_meta_form' || landingPageUrl.includes('fb.me') || landingPageUrl.includes('facebook.com/lead')) {
  return [{
    json: {
      ...$input.first().json,
      form_type: 'native_meta_form',
      landing_page_title: 'Formulaire natif Meta',
      landing_page_subtitle: '',
      landing_page_promise: 'Généré via Facebook',
      form_required_fields: $json.form_total_fields,
      form_optional_fields: 0,
      form_has_email: ($json.native_form_questions_plain || "").toLowerCase().includes('email'), email_field_name: 'email',
      form_has_phone: ($json.native_form_questions_plain || "").toLowerCase().includes('phone') || ($json.native_form_questions_plain || "").toLowerCase().includes('téléphone'), phone_field_name: 'phone',
      form_has_birth_date: false, birth_date_field_name: '',
      form_has_postal_code: ($json.native_form_questions_plain || "").toLowerCase().includes('post code'), postal_code_field_name: 'postal_code',
      form_has_social_status: false, social_status_field_name: '',
      cta_text: 'Envoyer',
      estimated_completion_time: '1 min',
      skip_html_fetch: true,
      tunnel_quality_score: 5,
      tunnel_friction_level: "low",
      tunnel_friction_reasons: "native_form_no_friction",
      tunnel_recommendations: "use_webhook_or_graph_api",
      tunnel_estimated_conversion_rate: 40
    }
  }];
}

return [{
  json: {
    ...$input.first().json,
    form_type: 'external_landing_page',
    landing_page_url: landingPageUrl,
    skip_html_fetch: !landingPageUrl
  }
}];

let input = {};
try {
  // CRITICAL FIX: To prevent data loss from the Fetch HTML node, 
  // we pull the original ad data directly from the Check node.
  input = $('Check Native Form').first().json;
} catch(e) {
  input = $input.first().json;
}

const currentItem = $input.first().json;
const html = currentItem.data || currentItem.body || '';

if (!html && input.skip_html_fetch !== true) {
  return [{
    json: {
      ...input,
      landing_page_title: 'Erreur: Page non accessible',
      form_type: 'error',
      form_fields_json: '',
      form_total_fields: 0, form_required_fields: 0, form_optional_fields: 0,
      form_has_email: false, email_field_name: '',
      form_has_phone: false, phone_field_name: '',
      form_has_birth_date: false, birth_date_field_name: '',
      form_has_postal_code: false, postal_code_field_name: '',
      form_has_social_status: false, social_status_field_name: '',
      cta_text: '',
      estimated_completion_time: ''
    }
  }];
}

const extractText = (m, fallback) => m ? m[1].replace(/<[^>]*>?/gm, '').trim() : fallback;
const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
const h2Match = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
const pMatch = html.match(/<p[^>]*>([\s\S]*?)<\/p>/i);

const landing_page_title = extractText(h1Match, 'Pas de titre');
const landing_page_subtitle = extractText(h2Match, '');
const landing_page_promise = extractText(pMatch, '').substring(0, 150);

const formFields = [];
for (const m of html.matchAll(/<input[^>]*>/gi)) {
    const n = (m[0].match(/name=["']([^"']*)["']/i) || [])[1];
    const t = (m[0].match(/type=["']([^"']*)["']/i) || [, 'text'])[1].toLowerCase();
    if(n && t !== 'hidden' && t !== 'submit') formFields.push({ name: n, type: t, required: /required/i.test(m[0]) });
}
for (const m of html.matchAll(/<select[^>]*>/gi)) {
    const n = (m[0].match(/name=["']([^"']*)["']/i) || [])[1];
    if(n) formFields.push({ name: n, type: 'select', required: /required/i.test(m[0]) });
}

let o = { email: false, phone: false, birth: false, postal: false, social: false };
let fN = { email: '', phone: '', birth: '', postal: '', social: '' };

formFields.forEach(f => {
    const n = f.name.toLowerCase();
    if (!o.email && (n.includes('email') || f.type === 'email' || n.includes('mail'))) { o.email = true; fN.email = f.name; }
    if (!o.phone && (n.includes('phone') || n.includes('tel') || f.type === 'tel')) { o.phone = true; fN.phone = f.name; }
    if (!o.birth && (n.includes('birth') || n.includes('date') || n.includes('age') || n.includes('naissance'))) { o.birth = true; fN.birth = f.name; }
    if (!o.postal && (n.includes('postal') || n.includes('code') || n.includes('zip') || n.includes('cp'))) { o.postal = true; fN.postal = f.name; }
    if (!o.social && (n.includes('status') || n.includes('regime') || n.includes('secu') || n.includes('situation'))) { o.social = true; fN.social = f.name; }
});

const ctaMatch = html.match(/<button[^>]*>([\s\S]*?)<\/button>/i) || html.match(/<input[^>]*type=["']submit["'][^>]*value=["']([^"']*)["']/i);

// For native forms, we usually already set form_type to 'native_form'. Let's preserve it or set it natively.
let final_form_type = input.form_type || 'external_landing_page';
if (html && html.includes('meta.com') && final_form_type !== 'native_form') final_form_type = 'native_meta';

return [{
  json: {
    ...input,
    landing_page_title: input.landing_page_title || landing_page_title,
    landing_page_subtitle: input.landing_page_subtitle || landing_page_subtitle,
    landing_page_promise: input.landing_page_promise || landing_page_promise,
    form_type: final_form_type,
    form_fields_json: input.form_fields_json || JSON.stringify(formFields),
    form_total_fields: input.form_total_fields || formFields.length,
    form_required_fields: input.form_required_fields || formFields.filter(f => f.required).length,
    form_optional_fields: input.form_optional_fields || (formFields.length - formFields.filter(f => f.required).length),
    form_has_email: input.form_has_email || o.email, email_field_name: input.email_field_name || fN.email,
    form_has_phone: input.form_has_phone || o.phone, phone_field_name: input.phone_field_name || fN.phone,
    form_has_birth_date: input.form_has_birth_date || o.birth, birth_date_field_name: input.birth_date_field_name || fN.birth,
    form_has_postal_code: input.form_has_postal_code || o.postal, postal_code_field_name: input.postal_code_field_name || fN.postal,
    form_has_social_status: input.form_has_social_status || o.social, social_status_field_name: input.social_status_field_name || fN.social,
    cta_text: input.cta_text || extractText(ctaMatch, 'Envoyer'),
    estimated_completion_time: input.estimated_completion_time || (Math.round((formFields.length * 0.5 + 0.5)) + " min")
  }
}];

parameters.text:
Tu es un expert mondial en optimisation de tunnels de conversion (CRO) et génération de leads (Assurance/Mutuelle Santé).

On vient de scraper les données du formulaire (ou de la Landing Page) après le clic sur la publicité.

**DONNÉES DU TUNNEL À ANALYSER**
Titre de la page: {{ $json.landing_page_title }}
Promesse de la page: {{ $json.landing_page_promise }}
Type de formulaire: {{ $json.form_type }} (native_meta = directement sur facebook/instagram, external_landing_page = site web)
Total des champs: {{ $json.form_total_fields }}
Champs obligatoires: {{ $json.form_required_fields }}
Demande un Email ? {{ $json.form_has_email }}
Demande un Téléphone ? {{ $json.form_has_phone }}
Demande la Date de naissance/Âge ? {{ $json.form_has_birth_date }}
Demande le Code Postal ? {{ $json.form_has_postal_code }}
Demande le Régime Social / Situation ? {{ $json.form_has_social_status }}
Texte du Bouton (CTA): {{ $json.cta_text }}
Temps d'inscription estimé: {{ $json.estimated_completion_time }}

**RÈGLES D'ANALYSE (Le "Deep Dive") SPÉCIAL LEAD MUTUELLE**
1. RÈGLE D'OR : En Mutuelle, OBTENIR LE NUMÉRO DE TÉLÉPHONE EST OBLIGATOIRE ET VITAL pour vendre au prospect. Le fait de demander le téléphone N'EST PAS UNE FRICTION ERREUR, c'est le but même du formulaire ! Ne baisse pas la note si le téléphone est demandé.
2. Un formulaire natif Meta sans question qualifiante a de super taux de clics (25%-45%) mais produit des leads souvent injoignables. Il faut recommander de rajouter 1 ou 2 questions qualifiantes (ex: Quel est l'âge ou le régime) pour filtrer les curieux.
3. Une landing page externe avec beaucoup de champs au début fait fuir. Recommande un tunnel "Multi-step" (une question simple d'abord, le numéro de téléphone tout à la fin) pour maximiser les conversions.
4. L'alignement de la promesse (Si la pub promet "Devis Rapide", le bouton final ne doit pas contredire la promesse).

**GÉNÈRE TON ANALYSE STRICTEMENT SOUS CE FORMAT JSON**
- tunnel_quality_score (De 1 à 10 : 10 = formulaire optimisé pour un lead mutuelle joignable)
- tunnel_friction_level ("low", "medium", "high")
- tunnel_friction_reasons (Array de chaînes courtes JSON : ex: ["long_single_page_form"])
- tunnel_recommendations (Array de recommandations courtes JSON : ex: ["use_multi_step_strategy", "add_trust_badge_under_phone"])
